    params: &CommitParams,
    dry: bool,
    land: Option<&LandPlan>,
) -> Result<(), Box<dyn std::error::Error>> {
    if let Some(land) = land {
        return crate::land::run(ctx, repo, publish.scope(), land, "@-", "the closing", dry);
