495	/// names the agent `@`. Pushes nothing, [`agent_publish`] does, after
496	/// the work half. Returns the partner's change id, where `main` ends,
497	/// and how `main` is published.
498	fn agent_half(
499	    ctx: &mut Context,
500	    pair: &Pair,
501	    work: &WorkCommit,
502	    params: &PushParams,
503	) -> Result<(String, AgentPublish), Box<dyn std::error::Error>> {
